function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 25) return 'The tree has at most 25 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 2147483647)) return 'Each node value is between 1 and 2^31 - 1.';
  // Rebuild the shape from the level-order list and check every parent.
  const queue = [root[0]];
  let i = 1;
  for (let q = 0; q < queue.length; q++) {
    const left = i < root.length ? root[i] : null;
    const right = i + 1 < root.length ? root[i + 1] : null;
    i += 2;
    if ((left === null) !== (right === null)) return 'Every node has either no children or exactly two.';
    if (left !== null) {
      if (queue[q] !== Math.min(left, right)) return 'Each parent must hold the smaller of its two children.';
      queue.push(left, right);
    }
  }
  if (i < root.length && root.slice(i).some(v => v !== null)) return 'The level-order list has values with no parent.';
  return null;
}

